#pragma declaration

inline float2x2 rotate(float v) {
    float a = cos(v);
    float b = sin(v);
    return float2x2(a,-b,b,a);
}

float smin(float a, float b, float k)
{
    float h = max(k-abs(a-b), 0.0)/k;
    return min(a, b) - h*h*k*(1.0/4.0);
}
half smin(half a, half b, half k)
{
    half h = max(k-abs(a-b), 0.h)/k;
    return min(a, b) - h*h*k*(1.h/4.h);
}
float smax(float a, float b, float k)
{
    return -smin(-a, -b, k);
}
half smax(half a, half b, half k)
{
    return -smin(-a, -b, k);
}

float box(float3 p, float3 b, float r)
{
    float3 q = abs(p) - b + r;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}
half box(half3 p, half3 b, half r)
{
    half3 q = abs(p) - b + r;
    return length(max(q, 0.h)) + min(max3(q.x,q.y,q.z), 0.h) - r;
}

float box2d(float2 p, float2 b, float r)
{
    float2 q = abs(p) - b + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

half box2d(half2 p, half2 b, half r)
{
    half2 q = abs(p) - b + r;
    return length(max(q, 0.h)) + min(max(q.x, q.y), 0.h) - r;
}

half squircle(half2 p, half2 b, half r)
{
    const float continuous_factor = 1.3;
    r *= continuous_factor;
    half2 hs = b - r;

    p = abs(p); 

    if(p.x < hs.x || p.y < hs.y ){
        return box2d(p, b, 0.);
    }

    p-= hs;
    p /= r;

    if( p.y>p.x ) {
        p=p.yx;
    };

    half n = 2.75;
    half w = pow(p.x,n) + pow(p.y,n);

    return (pow(w,1.0h/n) - 1.) * (r);

}



struct Blob {
    const float metaSmooth = 0.12;
    const float metaSize = 0.37;
    const float metaOffset = 0.18;
    const float offsetSpeed = 1.3;
    float4 rectangleData;
    float2 shapeData;


    // Precomputed value before raymarch loop
    float time10;
    float2x2 rot;
    float4 metaPosSize[4];
    float attractorsFade;

    void init(float time, float inertiaRotation, float showAttractors, float4 rectangle, float2 shape) {
        time10 = time*10.;
        rot = rotate(time*0.4*M_PI_2_F + inertiaRotation);

        // precalc metaball pos & size
        float ct = cos(time * offsetSpeed) * metaSize * metaOffset;
        float st = sin(time * offsetSpeed) * metaSize * metaOffset;
        metaPosSize[0] = float4( st*1.1, st,  0.0, metaSize * 1.);
        metaPosSize[1] = float4(-st*1.2, st,  0.21, metaSize * 1.0);
        metaPosSize[2] = float4( st * 1.4, ct * 1.3, -0.2,        metaSize * 1.0);
        metaPosSize[3] = float4( st * 1.2, -ct * 1.2,  0.1,        metaSize  );

        attractorsFade = 0.15 * showAttractors;
        rectangleData = rectangle;
        shapeData = shape;
    }


    half map(half3 p) {
        half d = 0.0, r = 0.0;
        half4 rect = half4(rectangleData);
        half2 shp = half2(shapeData.xy);

        if (rect.w < 1.0) {
            // Metaballs
            half3 pp = half3(half2x2(rot) * p.xy, p.z);
            half d0 = length(pp - half3(metaPosSize[0].xyz)) - half(metaPosSize[0].w);
            half d1 = length(pp - half3(metaPosSize[1].xyz)) - half(metaPosSize[1].w);
            half d2 = length(pp - half3(metaPosSize[2].xyz)) - half(metaPosSize[2].w);
            half d3 = length(pp - half3(metaPosSize[3].xyz)) - half(metaPosSize[3].w);

            half ms = metaSmooth;
            d = smin(d0, d1, ms);
            d = smin(d,d2, ms);
            d = smin(d,d3, ms);
        }
        if (rect.w > 0.0) {
            r = box(p, half3(rect.xy, 0.4h), rect.z);
        }
        d = mix(d, r, rect.w);
        //d = mix(d, shp.x, shp.y);
        return d;
    }

    float map(float3 p) {
        float d = 0.0, r = 0.0;
        float4 rect = float4(rectangleData);
        float2 shp = float2(shapeData.xy);

        if (rect.w < 1.0) {
            // Metaballs
            float3 pp = float3(float2x2(rot) * p.xy, p.z);
            float d0 = length(pp - float3(metaPosSize[0].xyz)) - float(metaPosSize[0].w);
            float d1 = length(pp - float3(metaPosSize[1].xyz)) - float(metaPosSize[1].w);
            float d2 = length(pp - float3(metaPosSize[2].xyz)) - float(metaPosSize[2].w);
            float d3 = length(pp - float3(metaPosSize[3].xyz)) - float(metaPosSize[3].w);

            float ms = metaSmooth;
            d = smin(d0, d1, ms);
            d = smin(d,d2, ms);
            d = smin(d,d3, ms);
        }
        if (rect.w > 0.0) {
            r = box(p, float3(rect.xy, 0.4), rect.z);
        }
        d = mix(d, r, rect.w);
        return d;
    }

    half map2d(half2 p) {
        half d = 0.0, r = 0.0;
        half4 rect = half4(rectangleData);
        half2 shp = half2(shapeData.xy);

        if (rect.w < 1.0) {
            half2 pp = half2x2(rot) * p;
            half d0 = length(pp - half2(metaPosSize[0].xy)) - half(metaPosSize[0].w);
            half d1 = length(pp - half2(metaPosSize[1].xy)) - half(metaPosSize[1].w);
            half d2 = length(pp - half2(metaPosSize[2].xy)) - half(metaPosSize[2].w);
            half d3 = length(pp - half2(metaPosSize[3].xy)) - half(metaPosSize[3].w);

            half ms = metaSmooth;
            d = smin(d0, d1, ms);
            d = smin(d,d2, ms);
            d = smin(d,d3, ms);
        }
        if (rect.w > 0.0)
        {
            //r = box2d(p.xy, rect.xy, rect.z);
            r = squircle(p.xy, rect.xy, rect.z);
        }
        d = mix(d, r, rect.w);
        //d = mix(d, shp.x, shp.y);
        return d;
    }


float trace(float3 ro_i, float3 rd_i) {

    half3 ro = half3(ro_i);
    half3 rd = half3(rd_i);
    float t = 0.;
    for(int i=0; i<15; i++) {
        half d = map(rd*t + ro);
        t += d;
        if (d < 0.005)
            return t;
    }
    return t;
}

    float3 normal(float3 p_i, float d) {
        half2 eps = half2(.02h, 0.h);
        half3 n;
        half3 p = half3(p_i);
        n.x = d - map(p-eps.xyy);
        n.y = d - map(p-eps.yxy);
        n.z = d - map(p-eps.yyx);
        return float3(normalize(n));
    }
};

//------------------------------------------------------
// Bindings
//------------------------------------------------------
#pragma arguments
texture2d image;
//texture2d shapeSDF;
texture1d colorLUT;
texture1d colorLUTBottom;
float2 position;
float intertiaRotation;
float scale;
float opacity;
float transitionToBlob;
float transitionToPicture;
float transitionToFinalPicture;
float transitionToRectangle;
float transitionToRectangleProcessing;
float transitionToError;
float transitionToShape;
float showImage;
float3 imageRatio_screenRatio;
float lightMode; //no bool or int in custom properties
float genmojiMode; //no bool or int in custom properties
//float wandMode;
float2 rectangleSize;
float rectangleRadius;
float imageScale;
float3 latency;
float blobAnimationSpeed;
float2 progress_intensity;
float2 image_size;
float progressCenterDimIntensity;
float glassClearRadius;
float maxInteriorDepth;


//------------------------------------------------------
// Entry point
//------------------------------------------------------
#pragma body
constexpr sampler smp_lin = sampler(filter::linear, address::repeat);
constexpr sampler smp_img = sampler(filter::linear, address::clamp_to_edge, mip_filter::linear, filter::linear ,mag_filter::linear, min_filter::linear);

float time = vfx_frame.time;

float latencyTime = latency.x;
float latencyIntensity = latency.y;
float latencyIntro = latency.z;

float imageRatio = imageRatio_screenRatio.x;
float2 screenRation = imageRatio_screenRatio.yz;

// Camera origin & direction
float2 uv = in.fragmentPosition.xy * vfx_frame.inverseResolution;
float3 ro = vfx_frame.inverseViewTransform.columns[3].xyz;

float2 texture_size = {(float)image.get_width(), (float)image.get_height()};
float2 image_scale = image_size / texture_size;

float2 effectPosition = position;
uv = (uv + effectPosition);

//for the wand
float2 shapeUV = uv;
uv += position;
half c = 0;

float2 ndc = float2(uv.x*2.-1., (1.-uv.y)*2.-1.) / scale;
float aspect = vfx_frame.projectionTransform.columns[1].y / vfx_frame.projectionTransform.columns[0].x;
float tanHalfFovY = 1.0f / vfx_frame.projectionTransform[1][1];
float3 rd = normalize( (ndc.x * vfx_frame.inverseViewTransform.columns[0].xyz * tanHalfFovY * aspect) + (ndc.y * vfx_frame.inverseViewTransform.columns[1].xyz * tanHalfFovY) - vfx_frame.inverseViewTransform.columns[2].xyz);

// Scene setup
Blob blob;
float rectangleCorner = min(rectangleSize.x, rectangleSize.y);
blob.init(vfx_frame.time * blobAnimationSpeed, intertiaRotation, 1. - transitionToPicture, float4(rectangleSize.xy,rectangleCorner, 0.0), float2(c,transitionToShape));

// Intersection with plane z = 0
half planeT = -half(ro.z)/half(rd.z);

half3 planeP = half3(ro) + half3(rd) * planeT;
planeP = select(planeP, half3(0.00001, 0.0, 0.0), dot(planeP, planeP) == 0.0); // avoid 0 to avoid NaN

half planeD = blob.map2d(planeP.xy);
half2 planeDir = normalize(half2(planeP.xy));

float genMult = 1;
if (genmojiMode > 0.5)
    genMult = 1.5;
float bgRadius = 1.1 * genMult;

if (planeD * bgRadius > 1.h) discard_fragment();

half4 col = half4(0.);


// Lights direction
float lightZ = mix(0.4, 3.5, pow(transitionToShape, 2));

float3 dirl1 = normalize(float3( 0.4, 0.7, lightZ * 0.2));
float3 dirl2 = normalize(float3( 0.4,-0.7, lightZ));
float3 dirl3 = normalize(float3(  -0.7, 0.4, lightZ));

float2 uvImg = float2(planeP.xy);

// Shade
float planeDThreshold = 0.005;
if (planeD < planeDThreshold) {
    // Trace
    float t = blob.trace(ro,rd);

    float3 p = ro + rd * t;
    float d = blob.map(half3(p));
    float3 n = blob.normal(p, d);


    // Fresnel
    float fre = saturate(1.+dot(rd,n));

    // ======= GLASS LIGHTING MODEL =======

    // === Clear zone: tunable transparent center ===
    float normalizedDepth = saturate(-float(planeD) / max(maxInteriorDepth, 0.001));
    float linearRamp = saturate(normalizedDepth / max(glassClearRadius, 0.001));

    // --- BEGIN OPTION 2: NORMAL-DRIVEN DEPTH VARIATION ---
    // Perturbs linearRamp based on how oblique the surface normal is relative to view.
    // Areas where normal faces camera = clearer; glancing normals = frostier.
    // TUNE: opt2_strength (0.0-0.4) = how much variation. 0 = disabled.
    //       Higher = more contrast between clear/frosted patches as blob deforms.
    float opt2_strength = 0.15;
    float normalViewAlignment = saturate(dot(n, -rd));
    linearRamp = saturate(linearRamp + (1.0 - normalViewAlignment) * opt2_strength - opt2_strength * 0.5);
    // --- END OPTION 2 ---

    half clearFade = half(pow(1.0 - linearRamp, 3.0));

    // --- BEGIN OPTION 1: ANGULAR SINE MODULATION ---
    // Modulates clearFade with animated sine waves around the blob's angular position.
    // Creates non-uniform frost thickness — some wedges thicker, some thinner.
    // TUNE: opt1_strength (0.0-0.5) = depth of modulation. 0 = disabled.
    //       opt1_speed (0.5-3.0) = animation speed. Lower = slow drift, higher = lively.
    //       opt1_octaves: comment out lines for fewer/simpler waves.
    float opt1_strength = 0.2;
    float opt1_speed = 1.0;
    float opt1_angle = atan2(float(planeP.y), float(planeP.x));
    float opt1_wave = 0.0;
    opt1_wave += 0.5 * sin(opt1_angle * 3.0 + time * opt1_speed * 0.8);   // broad 3-lobe
    opt1_wave += 0.3 * sin(opt1_angle * 5.0 - time * opt1_speed * 1.1);   // medium 5-lobe
    opt1_wave += 0.2 * sin(opt1_angle * 7.0 + time * opt1_speed * 1.5);   // fine 7-lobe
    clearFade *= 1.0h + half(opt1_wave * opt1_strength);
    clearFade = saturate(clearFade);
    // --- END OPTION 1 ---

    // Blinn-Phong specular (tight highlights for glass)
    float3 halfVec1 = normalize(dirl1 - rd);
    float3 halfVec2 = normalize(dirl2 - rd);
    float3 halfVec3 = normalize(dirl3 - rd);
    float l1_spec = pow(max(0., dot(n, halfVec1)), 64.);
    float l2_spec = pow(max(0., dot(n, halfVec2)), 64.);
    float l3_spec = pow(max(0., dot(n, halfVec3)), 64.);

    // Glass fresnel: purely angle-driven
    half bodyFresnel = half(pow(fre, 1.8));

    // --- Body: fake environment reflection ---
    float reflectAngle = atan2(n.y, n.x) / (M_PI_F * 2.0);
    half3 envReflect = (half3)colorLUT.sample(smp_lin, reflectAngle + time * 0.03).rgb;
    half3 envBase = half3(0.78h, 0.83h, 0.92h);
    envReflect = mix(envBase, envReflect, 0.4h);

    col.rgb = envReflect * bodyFresnel * 0.35h * clearFade;
    col.a = bodyFresnel * 0.25h * clearFade;

    // --- Primary specular: concentrated glass highlights ---
    half3 specColor = half3(0.97h, 0.98h, 1.0h);
    half specTotal = half(l1_spec * 0.6 + l2_spec * 0.5 + l3_spec * 0.55);
    col.rgb += specColor * specTotal * 1.8h * clearFade;
    col.a = saturate(col.a + specTotal * 0.8h * clearFade);

    // --- Secondary specular: wider, softer (internal light concentration) ---
    float3 halfVecInternal = normalize((dirl1 + dirl3) * 0.5 - rd);
    half internalSpec = half(pow(max(0., dot(n, halfVecInternal)), 8.)) * 0.2h;
    col.rgb += specColor * internalSpec * clearFade;

    // --- Fresnel rim: crisp with subtle edge dispersion ---
    half3 rimColor = mix(half3(1.0h, 0.95h, 0.9h), half3(0.85h, 0.92h, 1.0h), half(pow(fre, 0.5)));
    half rimIntensity = half(pow(fre, 3.0)) * 0.8h;
    col.rgb += rimColor * rimIntensity * clearFade;
    col.a = saturate(col.a + rimIntensity * 0.5h * clearFade);

    // --- BEGIN OPTION 4: CAUSTIC PATTERN ---
    // Animated bright concentration lines from virtual light dirs dotted with surface normal.
    // Simulates light focusing through curved glass. Moves organically with blob deformation.
    // TUNE: opt4_power1/2 (8-32) = line thinness. Higher = thinner sharper lines.
    //       opt4_intensity (0.1-0.5) = overall brightness of caustic lines.
    //       z components (0.3-0.8) in causticDir = how "overhead" the virtual lights are.
    //         Lower z = more side-lit = lines appear across more of the surface.
    //         Higher z = more top-down = lines concentrate near the rim.
    float opt4_intensity = 0.25;
    float opt4_power1 = 20.;
    float opt4_power2 = 14.;
    float3 causticDir1 = normalize(float3(sin(time * 0.4), cos(time * 0.3), 0.5));
    float3 causticDir2 = normalize(float3(cos(time * 0.5), sin(time * 0.7), 0.4));
    half caustic1 = half(pow(max(0., dot(n, causticDir1)), opt4_power1));
    half caustic2 = half(pow(max(0., dot(n, causticDir2)), opt4_power2));
    half causticPattern = (caustic1 + caustic2 * 0.7h) * clearFade;
    col.rgb += half3(0.9h, 0.95h, 1.0h) * causticPattern * half(opt4_intensity);
    col.a = saturate(col.a + causticPattern * half(opt4_intensity * 0.6));
    // --- END OPTION 4 ---

    // ======= END GLASS LIGHTING MODEL =======

    // Gamma: tighter for glass contrast (less washout)
    col = pow(col, mix(0.85h, 0.75h, half(transitionToPicture)));

    float2 uvImg = float2(planeP.xy);
    float rampUV = atan2(uvImg.y, uvImg.x) - atan2(rectangleSize.y, rectangleSize.x);
    rampUV = fract(rampUV / (M_PI_F * 2.)) - 0.5;

    // Latency effect
    float offsetLatency = latencyTime * M_PI_F * 2. - 1.;
    float2 latencyUV = 0.09 * float2(cos(offsetLatency), sin(-offsetLatency));
    half4 latencyCol = (half4)colorLUT.sample(smp_lin, rampUV + 0.45  + latencyTime) * (1 + latencyIntro);
    half latencyLum = dot(latencyCol.rgb, half3(0.299h, 0.587h, 0.114h));
    latencyCol.rgb = mix(half3(latencyLum), latencyCol.rgb, 0.25h);
    latencyCol = pow(latencyCol, 0.5);
    float latencyBoxDist = box2d(latencyUV - uvImg, 0.75 * rectangleSize.xy, 0.75 * rectangleCorner) * transitionToFinalPicture;
    float latencyInt = 0.5 * pow(smoothstep(-0.25, 0.2, latencyBoxDist), 3.);
    latencyCol *= saturate(latencyInt * (latencyIntensity - 0.5 * latencyIntro));
    latencyCol.a *= 0.5h * 0.65h;

    col = (1. - latencyCol.a) * col + latencyCol;

    col *= transitionToFinalPicture * (pow(transitionToShape, 5) * 1.5h + 1.0h);

    // Processing effect: frosted glass appearance
    half4 process_img = 0;
    float fre2 = saturate(1.+dot(normalize(rd + float3(-0.2,0.6,0)),n));
    process_img += half4(0.35h, 0.38h, 0.42h, 1.0h) * 0.4h;
    process_img.rgb *= 0.3;

    process_img = pow(process_img * 0.25, 0.6);
    process_img.a = 0.55h * mix(0.15h, 1.0h, clearFade);

    process_img *= 0.5;
    process_img = mix(process_img, 0.5, transitionToError);

    float show_image_val = mix(showImage, 1., transitionToError);

    // Final image
    half4 img = 0.;
    if (genmojiMode < 0.5)
    {
        float imageScaleUnzoom = imageScale * 0.9;
        imageScaleUnzoom *= imageRatio;


        float w = vfx_frame.inverseResolution.y / imageRatio;
        float r = w / vfx_frame.inverseResolution.x;
        float off = 0.5 * (1.0 - r);

        float2 imageUV = float2(uv.x * r, uv.y);
        imageUV.x += off;

        imageUV = imageUV * imageScaleUnzoom + 0.5 * (1-imageScaleUnzoom);

        if (imageRatio<1)
            imageUV.y -= 0.15 * imageRatio;
        float2 imageUVcentered = imageUV * 2. - 1.;

        // --- BEGIN TEMPORAL AA JITTER ---
        // Sub-pixel time-based UV offset + LOD bias for anti-aliasing fine details.
        // Jitter moves the whole image together (temporal, not spatial) — invisible to eye.
        // LOD bias is the primary AA tool: pushes mipmap selection higher = softer details.
        // TUNE: aa_jitter_amp (0.0005-0.002). Sub-pixel motion for temporal averaging.
        //       aa_lod_bias (0.0-1.5). Higher = softer fine detail, less aliasing.
        //                              0.3-0.5 = mild, 0.7-0.8 = strong, 1.0+ = noticeably soft.
        //       Set both to 0 to disable.
        float aa_jitter_amp = 0.001;
        float aa_lod_bias = 0.5;
        float2 uvOffset = float2(cos(time * 2.2 + 0.3), sin(time * 1.6)) * aa_jitter_amp;
        // --- END TEMPORAL AA JITTER ---

        {
            float refractionMask = 1.0 - saturate(normalizedDepth * 2.0);
            imageUV.xy -= blob.normal(p, d).xy * float2(-1, 1) * pow(fre, 1) * 0.1 * refractionMask;

            float2 uvColorOffset = -0.06 * imageUVcentered * smoothstep(-0.3, 0.3, float(planeD));
            // --- BEGIN CHROMATIC ABERRATION STRENGTH ---
            // Multiplier on the chromatic aberration UV split. Original uses 1.0.
            // Causes colored halos around high-contrast features (text, etc).
            // TUNE: ca_strength (0.0-1.0). 0 = disabled (no halos, no chromatic effect).
            //       0.3 = subtle, 0.5 = moderate, 1.0 = original strength.
            float ca_strength = 0.3;
            uvColorOffset *= ca_strength;
            // --- END CHROMATIC ABERRATION STRENGTH ---
            uvOffset += -0.1 * imageUVcentered * max(0., length(imageUVcentered - uvOffset) - 0.75);


            imageUV.x *= image_scale.x;
            uvOffset.x *= image_scale.x;


            float4 sample1 = image.sample(smp_img, imageUV + uvOffset + uvColorOffset, bias(aa_lod_bias));
            float4 sample2 = image.sample(smp_img, imageUV + uvOffset + 0.5 * uvColorOffset, bias(aa_lod_bias));
            float4 sample3 = image.sample(smp_img, imageUV + uvOffset, bias(aa_lod_bias));
            float4 sample4 = image.sample(smp_img, imageUV + uvOffset - 0.5 * uvColorOffset, bias(aa_lod_bias));
            float4 sample5 = image.sample(smp_img, imageUV + uvOffset - uvColorOffset, bias(aa_lod_bias));

            // --- BEGIN SCREEN-SPACE SUPERSAMPLING ---
            // Use screen-space derivatives to find how big one screen pixel is in UV space.
            // Then sample at offsets matching that scale — proper manual AA.
            // This emulates what mipmaps would do, for textures without mipmaps.
            // TUNE: aa_ss_strength (0.0-2.0). 0 = disabled.
            //       0.5 = mild softening, 1.0 = matches one screen pixel (proper AA),
            //       2.0 = aggressive blur (very soft).
            //       aa_ss_blend (0.0-1.0). How much supersampled vs chromatic aberration.
            //       0 = full CA, no AA. 1 = full AA, no CA. Trade one for the other.
            //       0.5-0.8 = balanced.
            //       aa_ss_min_radius (0.0-0.005). Minimum UV-space AA offset, applied
            //       even when close to the camera. Prevents magnification aliasing
            //       (visible texel grid edges when texture is upscaled).
            //       0.001 = subtle floor, 0.003 = ensures soft text at any distance.
            float aa_ss_strength = 1.0;
            half aa_ss_blend = 0.8h;
            float aa_ss_min_radius = 0.0016;
            float2 uvDx = dfdx(imageUV + uvOffset);
            float2 uvDy = dfdy(imageUV + uvOffset);
            float2 dxAbs = abs(uvDx);
            float2 dyAbs = abs(uvDy);
            uvDx = sign(uvDx + 1e-8) * max(dxAbs, float2(aa_ss_min_radius));
            uvDy = sign(uvDy + 1e-8) * max(dyAbs, float2(aa_ss_min_radius));
            float2 ssOff1 = (uvDx * 0.5 + uvDy * 0.25) * aa_ss_strength;
            float2 ssOff2 = (-uvDx * 0.25 + uvDy * 0.5) * aa_ss_strength;
            float2 ssOff3 = (-uvDx * 0.5 - uvDy * 0.25) * aa_ss_strength;
            float2 ssOff4 = (uvDx * 0.25 - uvDy * 0.5) * aa_ss_strength;
            half4 ss1 = (half4)image.sample(smp_img, imageUV + uvOffset + ssOff1);
            half4 ss2 = (half4)image.sample(smp_img, imageUV + uvOffset + ssOff2);
            half4 ss3 = (half4)image.sample(smp_img, imageUV + uvOffset + ssOff3);
            half4 ss4 = (half4)image.sample(smp_img, imageUV + uvOffset + ssOff4);
            half4 ssAvg = (ss1 + ss2 + ss3 + ss4) * 0.25h;
            // --- END SCREEN-SPACE SUPERSAMPLING ---

            // Compose chromatic aberration result first
            half4 caImg;
            caImg.r = sample1.r * 0.3333 + sample2.r * 0.6666;
            caImg.g = sample3.g * 0.5 + sample2.g * 0.25 + sample4.g * 0.25;
            caImg.b = sample4.b * 0.6666 + sample5.b * 0.3333;
            caImg.a = 0.11111 * sample1.a + 0.22222 * sample2.a + 0.33333 * sample3.a + 0.22222 * sample4.a + 0.11111 * sample5.a;
            // Blend chromatic aberration against full supersampled average
            img = mix(caImg, ssAvg, aa_ss_blend);
        }
        img *= (0.1 + 0.9 * smoothstep(1.8, 0.55, length(imageUVcentered)));//vignette
        img *= smoothstep(1.05, 0.9, length(imageUVcentered));//outside vignette

        img = mix(process_img, img, transitionToPicture * (1-transitionToRectangleProcessing));
        img *= saturate(show_image_val + 0.8);
    }

    col = (1.h-col.a) * img + col;
    half4 processBlended = mix(process_img * show_image_val, col, col.a);
    half processSuppression = half(saturate(normalizedDepth * 1.5));
    processSuppression = max(processSuppression, (1.0h - img.a) * half(transitionToPicture));
    col = mix(processBlended, col, processSuppression * half(transitionToPicture));

    // Rim glow: soft bright band at glass boundary, blends inward
    half rimGlowBand = smoothstep(0.015h, 0.0h, planeD) * smoothstep(-0.05h, -0.005h, planeD);
    col.rgb += half3(0.85h, 0.9h, 1.0h) * rimGlowBand * 0.3h * clearFade;
    col.a = saturate(col.a + rimGlowBand * 0.25h * clearFade);

    // Edge fade
    col *= smoothstep(0.006, -0.004, float(planeD));
}

// Background: subtle rippling glow for glass
half4 background = half4(0);

{
    float2 ve = float2(planeDir);
    float angle  = atan2(ve.y, ve.x)  / (M_PI_F * 2);

    float bgRadius = 1.1;
    float s = -0.005;

    // Base glow falloff
    float glowFalloff = saturate(pow(planeD <= s ? 0. : 1. - planeD * bgRadius , 5.)) * smoothstep(0.0, 1.0, transitionToBlob);

    // Ripple: animated wobble on the glow edge
    float rippleAngle = angle * M_PI_F * 2.0;
    float ripple = 0.0;
    ripple += 0.35 * sin(rippleAngle * 3.0 + time * 1.2);
    ripple += 0.25 * sin(rippleAngle * 5.0 - time * 0.8);
    ripple += 0.15 * sin(rippleAngle * 7.0 + time * 1.7);
    float rippleMask = saturate(glowFalloff * (1.0 + ripple * 0.4));

    half3 glowColor = half3(0.65h, 0.72h, 0.85h);
    half3 glowMask;
    glowMask.r = dot(planeDir, half2(dirl1.xy));
    glowMask.g = dot(planeDir, half2(dirl2.xy)) + 0.3h;
    glowMask.b = dot(planeDir, half2(dirl3.xy));
    glowMask = smoothstep(0.02h, 1.0h, pow(max(glowMask + 0.3h, 0.0h), 2.0h));
    half3 lut1 = (half3)colorLUT.sample(smp_lin, 0.75h + (time*0.3h) * 0.5h + 0.5h).rgb;
    half3 lut2 = (half3)colorLUT.sample(smp_lin, 0.75h + (time*0.8h) * 0.5h).rgb;
    half3 lut3 = (half3)colorLUTBottom.sample(smp_lin, 0.75h + (time*1.1h*0.5h)).rgb;
    half3 tintedGlow = mix(glowColor, lut1, 0.3h) * glowMask.r
                     + mix(glowColor, lut2, 0.3h) * glowMask.b
                     + mix(glowColor * half3(1.0h, 0.97h, 0.93h), lut3, 0.3h) * glowMask.g;
    tintedGlow /= max(glowMask.r + glowMask.g + glowMask.b, 0.000001h);

    background.rgb = tintedGlow;
    background.a = half(rippleMask) * 0.25h * 0.5h;

    background.rgb = pow(background.rgb, 0.85h);
    background.rgb *= background.a;
}


// Composite
col = background * (1.0h-col.a) * transitionToFinalPicture + col;
col = half4(col) * opacity;

// Error mode
half3 errorCol = mix(half3(0.26,0.14,0.01), half3(0.85,0.34,0.0), lightMode);
col.rgb = mix(col.rgb, errorCol * col.a, transitionToError);

_output.color = (float4)col;

#pragma declaration

inline float2x2 rotate(float v) {
    float a = cos(v);
    float b = sin(v);
    return float2x2(a,-b,b,a);
}

//------------------------------------------------------
// Blob
//------------------------------------------------------
struct Blob {
    const float metaSmooth = 0.12;
    const float metaSize = 0.37;
    const float metaOffset = 0.18;
    const float offsetSpeed = 1.3;

    float smin(float a, float b, float k)
    {
        float h = max(k-abs(a-b), 0.0)/k;
        return min(a, b) - h*h*k*(1.0/4.0);
    }

    // Precomputed value before raymarch loop
    float2x2 rot;
    float4 metaPosSize[4];

    void init(float time) {
        rot = rotate(time*0.4*M_PI_2_F);

        // precalc metaball pos & size
        float ct = cos(time * offsetSpeed) * metaSize * metaOffset;
        float st = sin(time * offsetSpeed) * metaSize * metaOffset;
        metaPosSize[0] = float4( st*1.1, st,  0.0, metaSize * 1.15);
        metaPosSize[1] = float4(-st*1.1, st,  0.2, metaSize * 1.15);
        metaPosSize[2] = float4(     st, ct,-0.24,        metaSize);
        metaPosSize[3] = float4(     st,-ct,  0.1,        metaSize);
    }


    float map(float2 p) {
        float2 pp = rot * p;
        float d0 = length(pp - metaPosSize[0].xy) - metaPosSize[0].w;
        float d1 = length(pp - metaPosSize[1].xy) - metaPosSize[1].w;
        float d2 = length(pp - metaPosSize[2].xy) - metaPosSize[2].w;
        float d3 = length(pp - metaPosSize[3].xy) - metaPosSize[3].w;

        float d = smin(d0, d1, metaSmooth);
        d = smin(d,d2, metaSmooth);
        d = smin(d,d3, metaSmooth);

        return d;
    }

    float3 normal(float2 p, float d) {
        float2 eps = float2(.01, 0.);
        float3 n;
        n.x = d - map(p-eps.xy);
        n.y = d - map(p-eps.yx);
        return n /= eps.x*2.;
    }
};



#pragma arguments
float lightMode,
float radius,
float2 screenRatio,
float2 applePosition,
float transitionToBlob,
float2 blobPosition,
float blobDimensions,
float blobAnimationSpeed,
float appleScale,
float isHDR,
texture2d inSDF,
texture1d inRamp

#pragma body
constexpr sampler smp_repeat(filter::linear, address::repeat);
constexpr sampler smp_border_white(filter::linear, address::clamp_to_edge, border_color::opaque_white);
float time = vfx_frame.time;

float2 uv = _surface.diffuseTexcoord;
float2 effectPosition = mix(applePosition, blobPosition, transitionToBlob);
effectPosition.x *= -1.;
float2 appleScale2 = mix(appleScale, blobDimensions, transitionToBlob);
float2 UVapple = (uv - 0.5) + effectPosition ;
UVapple *= screenRatio;
UVapple /= appleScale2;
UVapple += 0.5;

half c = inSDF.sample(smp_border_white, float2(UVapple.x, UVapple.y)).x;

//gradient
const float texWidth = inSDF.get_width();
const float kStep = 8./texWidth;
const float2 eps = float2(kStep, 0.);
float2 grad =  float2(inSDF.sample(smp_border_white, UVapple + eps.xy).x - inSDF.sample(smp_border_white, UVapple - eps.xy).x,
                      inSDF.sample(smp_border_white, UVapple + eps.yx).x - inSDF.sample(smp_border_white, UVapple - eps.yx).x);
grad /= (2.*kStep); // normalize

// blob
if (transitionToBlob > 0.0001)
{
    float2 uvBlob = (float2(uv.x, uv.y) - 0.5) + float2(effectPosition.x, effectPosition.y);
    uvBlob.y = -uvBlob.y;
    uvBlob *= screenRatio;
    uvBlob /= blobDimensions;

    Blob blob;
    blob.init(time * blobAnimationSpeed);
    float blobD = blob.map(uvBlob);

    c = mix(c, half(blobD), half(transitionToBlob));
    grad = mix(grad, blob.normal(uvBlob, blob.map(uvBlob)).xy, transitionToBlob);
}

// ramp
float rampUV = atan2(grad.x, grad.y);
rampUV = (rampUV + M_PI_F) / (M_PI_F * 2);
rampUV += fract(time * 0.13);
float4 rampColor = inRamp.sample(smp_repeat, rampUV);
float colorMult = mix(1.1,1.1,lightMode);
//if (isHDR>0.5)
//    colorMult = mix(1.1,1.1,lightMode); //HDR
rampColor.rgb = pow(rampColor.rgb * colorMult, mix(0.6,0.7,lightMode));


// outline
half outlineWidth = radius;
half smooth = 20 / texWidth;
float outline = smoothstep(outlineWidth+0.h, outlineWidth-smooth, abs(c));

//trying to add the lighter border colors
outlineWidth *= 0.95;
float outline2 = 0.0 * smoothstep(outlineWidth + 0.001h, outlineWidth - 0.001h, abs(c)) * pow(smoothstep(outlineWidth - 0.05h, outlineWidth + 0.000h, abs(c)), 5.h);

float outline3 = 1 * smoothstep(outlineWidth + 0.001h, outlineWidth - 0.004h, abs(c)) * pow(smoothstep(outlineWidth - 0.14h, outlineWidth + 0.000h, abs(c)), 5.h);
outline3 = pow(outline3, 1.3);

outline2 += outline3;
float insideMult = mix(0.1, 0.3,lightMode);

//
outlineWidth *= 0.5;
if (lightMode < 0.5)
{
    rampColor.rgb *=  1 + 0.5 * outline2; 

    //outside ramp
    outline += pow(smoothstep(outlineWidth + 0.26h, outlineWidth - 0.01h, abs(c)), 3.9h) * 0.7; 
}
else
{
    rampColor.rgb *=  1 + 0.4 * outline2; 

    //outside ramp
    outline += pow(smoothstep(outlineWidth + 0.18h, outlineWidth - 0.01h, abs(c)), 3.5h) * 0.7; 
}


float4 out_color = float4(rampColor) *  saturate(outline);
_output.color = float4(out_color * pow(1-transitionToBlob, 2));
